import { useState } from 'react';
import { Pressable, StyleSheet, Text, View } from 'react-native';

export default function App() {
  const [done, setDone] = useState(0);

  return (
    <View style={styles.screen}>
      <Text>Выполнено: {done}</Text>
      <Pressable
        accessibilityRole="button"
        accessibilityLabel="Отметить занятие выполненным"
        onPress={() => setDone(value => value + 1)}
        style={({ pressed }) => [styles.button, pressed && styles.pressed]}
      >
        <Text style={styles.buttonText}>Отметить</Text>
      </Pressable>
      <Pressable
        accessibilityRole="button"
        accessibilityLabel="Сбросить счётчик"
        onPress={() => setDone(0)}
        style={({ pressed }) => [styles.button, styles.reset, pressed && styles.pressed]}
      >
        <Text style={styles.buttonText}>Сбросить</Text>
      </Pressable>
    </View>
  );
}

